"""Self-contained reviewed read-only audit; no download, deploy, startup or DB writes."""
import base64
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile

REVIEWED_COMMIT = "883e063a760d5b2ceb15f91a37fcea24acdae783"
EXPECTED_ENVIRONMENT = {
    "RAILWAY_PROJECT_ID":"c1a9635c-789b-4e42-ac9b-cca4326fab9a",
    "RAILWAY_SERVICE_ID":"ecbfc64a-75d8-47b2-9b25-b2f7467e77e6",
    "RAILWAY_ENVIRONMENT_ID":"fcab95f8-3e30-4da9-8e0b-d9b7f94747ce",
}
MODULES = {
    "api_security.py":"1c543635d512699a2b5d7d0f4f01383f20892edcedef20c02cf5f6e597a6cc3b",
    "serve.py":"1560fb9dcada02ccaa76e28d72efac6f06c0e25d5e7a5fa83857d13dc5894082",
    "security_readonly_audit.py":"8e2c7acb526ea82ddff23c374ffe068ed177ff3f8070719b461087bd3c8c2b59",
}


BUNDLED_SOURCES = {'api_security.py': '', 'serve.py': '', 'security_readonly_audit.py': ''}

def reviewed_sources():
    sources = {}
    if set(BUNDLED_SOURCES) != set(MODULES):
        raise ValueError("Reviewed source set mismatch")
    for name, digest in MODULES.items():
        data = base64.b64decode(BUNDLED_SOURCES[name], validate=True)
        if len(data)>128*1024 or hashlib.sha256(data).hexdigest()!=digest:
            raise ValueError("Reviewed source verification failed")
        sources[name]=data
    return sources


CONFIG_KEYS = {"public_registration_disabled","paid_discovery_disabled","api_docs_disabled","jwt_format_valid","https_origins_configured","proxy_configuration_valid","proxy_trust_configured"}
AUTH_KEYS = {"query_completed","authenticated","privilege_details_available","privileges_require_review"}
FINDING_KEYS = {name+suffix for name in ("users","leads","tasks","documents") for suffix in ("_missing_id","_duplicate_id_groups")}
FINDING_KEYS |= {"users_missing_email","users_duplicate_email_groups","users_unknown_role","documents_missing_gridfs_object"}
FINDING_KEYS |= {name+suffix for name in ("leads","tasks") for suffix in ("_missing_owner","_orphan_owner")}
FINDING_KEYS |= {name+"_orphan_lead" for name in ("documents","tasks","interactions")}
INCOMPLETE_KEYS = {name+"_identity" for name in ("users","leads","tasks","documents")}
INCOMPLETE_KEYS |= {"users_access","leads_ownership","tasks_ownership","documents_lead_reference","tasks_lead_reference","interactions_lead_reference","gridfs_document_references","storage_configuration"}
MANUAL_KEYS = {"actual_proxy_peer_and_header_sanitization","database_persistence_and_recovery_policy","effective_storage_privacy_and_object_reference_coverage","authorized_published_account_flows","content_malware_and_capacity_policy","administrative_access_and_MFA_policy"}

def safe_summary(report):
    config=report["configuration_checks"];auth=report["authentication"];findings=report["finding_counts"]
    if set(config)!=CONFIG_KEYS or any(type(v) is not bool for v in config.values()):
        raise ValueError("Unexpected configuration result")
    if set(auth)!=AUTH_KEYS or any(v is not None and type(v) is not bool for v in auth.values()):
        raise ValueError("Unexpected authentication result")
    if not set(findings)<=FINDING_KEYS or any(type(v) is not int or v<0 for v in findings.values()):
        raise ValueError("Unexpected findings result")
    if not set(report["incomplete_checks"])<=INCOMPLETE_KEYS or set(report["manual_evidence_required"])!=MANUAL_KEYS or type(report["automated_checks_passed"]) is not bool:
        raise ValueError("Unexpected check identifiers")
    return {"audit_completed":True,"read_only":True,"production_certified":False,
            "automated_checks_passed":report["automated_checks_passed"],
            "configuration_checks":config,"authentication":auth,
            "finding_flags":{key:value>0 for key,value in findings.items()},
            "incomplete_checks":report["incomplete_checks"],
            "manual_evidence_required":report["manual_evidence_required"]}


def run():
    if any(os.environ.get(key)!=value for key,value in EXPECTED_ENVIRONMENT.items()):
        raise ValueError("Target environment not confirmed")
    sources=reviewed_sources()  # Verify every embedded module before importing any of them.
    with tempfile.TemporaryDirectory(prefix="ibiag-readonly-verified-") as directory:
        os.chmod(directory,0o700)
        for name,data in sources.items():
            target=Path(directory,name);target.write_bytes(data);target.chmod(0o600)
        command="import sys;sys.path.insert(0,sys.argv[1]);import security_readonly_audit;raise SystemExit(security_readonly_audit.main())"
        result=subprocess.run([sys.executable,"-I","-B","-c",command,directory],
                              capture_output=True,text=True,timeout=180)
        if result.returncode not in (0,1) or len(result.stdout)>65536:
            raise ValueError("Audit execution not confirmed")
        report=json.loads(result.stdout)
        if report.get("read_only") is not True or report.get("production_certified") is not False:
            raise ValueError("Unexpected audit output")
        print(json.dumps(safe_summary(report),ensure_ascii=False,sort_keys=True))
        return result.returncode


def main():
    try: return run()
    except (Exception,KeyboardInterrupt):
        print(json.dumps({"audit_completed":False,"production_certified":False,
                          "error":"Auditoria nao confirmada. Verifique sessao/alvo/rede; detalhes nao sao exibidos."},ensure_ascii=False),file=sys.stderr)
        return 2


if __name__=="__main__":
    raise SystemExit(main())
